pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 units, address actor) public {
        // units in 0.05 ether steps from 0.05 up to 9.95 ether: never 10 ether
        units = bound(units, 1, 199);
        vm.assume(actor != address(c));
        uint256 amount = units * 0.05 ether;
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: amount}() { ok = true; } catch { ok = false; }
        // Rule: any deposit not equal to exactly 10 ether must be rejected
        assertTrue(ok == false, "non-10-ether deposit must revert");
    }
}

