import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(t >= 1);
        vm.warp(t);

