pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, uint256 ts, uint256 blockNumber) public {
        // the fallback only accepts exactly 10 ether
        vm.assume(amount == 10 ether);
        // timestamp must be strictly greater than the stored pastBlockTime (starts at 0)
        vm.assume(ts > c.pastBlockTime());
        vm.assume(ts < type(uint256).max - 1);
        // the payout is a transfer to msg.sender, so the caller must be able to receive ETH:
        // route the call through a minimal payable caller contract
        Caller caller = new Caller(address(c));
        vm.deal(address(caller), amount);
        vm.warp(ts);
        vm.roll(blockNumber);
        caller.go();
        // General rule: after an admissible call, the contract's balance is drained iff block.number % 15 == 0
        assertTrue((address(c).balance == 0) == (blockNumber % 15 == 0));
    }
}

contract Caller {
    C c;
    constructor(C _c) { c = _c; }
    function go() external {
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback failed");
    }
    receive() external payable {}
}

