pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter r;

    function setUp() public {
        c = new C{value: 10 ether}();
        r = new Reverter();
    }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        blockNumber = bound(blockNumber, 1, type(uint256).max - 1);
        timestamp = bound(timestamp, 1, type(uint256).max - 2);
        vm.roll(blockNumber);
        vm.warp(timestamp);

        uint256 amt = 10 ether;
        vm.deal(address(r), amt);
        vm.prank(address(r));

        bool ok;
        (bool success, ) = address(c).call{value: amt}("");
        ok = success;

        // Rule: the call succeeds iff the block is NOT divisible by 15,
        // because C pays out exactly on divisible blocks and the payer-side
        // transfer to the reverting recipient then reverts the whole call.
        assertTrue(ok == (blockNumber % 15 != 0));
    }
}

// Adversarial counterparty: reverts whenever it receives ether.
contract Reverter {
    fallback() external payable {
        revert();
    }
    receive() external payable {
        revert();
    }
}

