    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 k) public {
        // choose an arbitrary positive multiple of 15 as the block number
        uint256 n = bound(k, 1, 10**9);
        uint256 blk = n * 15;
        vm.roll(blk);
        vm.warp(blk + 1);

        // caller is a funded contract that can receive the payout
        Caller caller = new Caller();
